html:
{#- The purchase order to the supplier (SP-82): one dated section per delivery batch. -#}
{% extends "smart_power/templates/print/base_rtl.html" %}
{%- set po = po_print(doc) -%}
{% block title %}
<table class="sp-quote-head">
	<tr>
		<td>
			<h2>{{ _("Purchase Order") }}</h2>
			<div>{{ _("No.") }}: <span class="sp-num">{{ po.header.po_no }}</span>{% if po.header.station %} · {{ _("Station") }} <span class="sp-num">{{ po.header.station }}</span>{% endif %}</div>
		</td>
		<td class="sp-quote-meta"><div>{{ _("Date") }}: {{ po.header.date }}</div></td>
	</tr>
	<tr>
		<td>{{ _("Supplier") }}: <strong>{{ po.header.supplier or "" }}</strong></td>
		<td class="sp-quote-meta">{%- if po.header.destination %}<div>{{ _("Delivery Destination") }}: {{ po.header.destination }}</div>{% endif %}</td>
	</tr>
</table>
{% endblock %}
{% block body %}
{{ sp_block("Purchase Order", "preamble", doc) }}

{%- for batch in po.batches %}
<h3 class="sp-po-batch">{{ _("Batch") }} <span class="sp-num">{{ batch.no }}</span> · {{ _("Delivery Date") }}: {{ batch.date }}</h3>
<table class="sp-table sp-po-lines">
	<thead>
		<tr>
			<th>#</th><th>{{ _("Description") }}</th><th>{{ _("Unit") }}</th><th>{{ _("Qty") }}</th>
			{%- if po.show_prices %}<th>{{ _("Unit Price") }}</th><th>{{ _("Total") }}</th>{% endif %}
		</tr>
	</thead>
	<tbody>
	{%- for line in batch.lines %}
		<tr>
			<td class="sp-num">{{ line.no }}</td>
			<td>{{ line.description or "" }}</td>
			<td>{{ _(line.uom) if line.uom else "" }}</td>
			<td class="sp-num">{{ frappe.format(line.qty, {"fieldtype": "Float"}) }}</td>
			{%- if po.show_prices %}
			<td class="sp-amount">{{ money(line.rate, po.currency) }}</td>
			<td class="sp-amount">{{ money(line.amount, po.currency) }}</td>
			{%- endif %}
		</tr>
	{%- endfor %}
	{%- if po.show_prices %}
		<tr class="sp-po-batch-total"><td colspan="5">{{ _("Batch Total") }}</td><td class="sp-amount">{{ money(batch.total, po.currency) }}</td></tr>
	{%- endif %}
	</tbody>
</table>
{%- endfor %}

{%- if po.show_prices %}
<table class="sp-quote-totals">
	<tr class="sp-quote-grand"><td>{{ _("Total") }}</td><td class="sp-amount">{{ money(po.total, po.currency) }}</td></tr>
</table>
<p class="sp-words">{{ _("Only") }} {{ po.words }} {{ _("no more") }}</p>
{%- endif %}

{%- for block in sp_blocks("Purchase Order", doc, ["preamble"]) %}{{ block }}{% endfor %}
{% endblock %}
{% block signatures %}
{{ signature_block(_("The supplier"), _("Smart Power")) }}
{% endblock %}
